const masterQuestionBank = [
            // Chapter 1: Number Systems
            { chapter: "Ch 1: Number System", question: "Which of the following is an irrational number?", options: ["√4", "3.14", "√7", "22/7"], correct: 2, explanation: "√7 is irrational because 7 is not a perfect square, meaning its decimal expansion is non-terminating and non-repeating." },
            { chapter: "Ch 1: Number System", question: "Every rational number is:", options: ["A whole number", "A natural number", "An integer", "A real number"], correct: 3, explanation: "The set of real numbers includes all rational and irrational numbers. Not every rational number (like 1/2) is an integer or whole number." },
            { chapter: "Ch 1: Number System", question: "The value of (256)^(0.16) × (256)^(0.09) is:", options: ["4", "16", "64", "256"], correct: 0, explanation: "Using the law of exponents: a^m × a^n = a^(m+n). So, 256^(0.16 + 0.09) = 256^0.25 = 256^(1/4). The 4th root of 256 is 4." },
            { chapter: "Ch 1: Number System", question: "Every rational number can be expressed as a decimal which is:", options: ["Terminating only", "Non-terminating only", "Terminating or non-terminating repeating", "Non-terminating non-repeating"], correct: 2, explanation: "Rational numbers always have decimal expansions that either terminate completely (like 0.5) or repeat a pattern endlessly (like 0.333...)." },
			{ chapter: "Ch 1: Number System", question: "Between any two distinct rational numbers, there are:", options: ["No rational numbers", "Exactly one rational number", "Infinitely many rational numbers", "Only irrational numbers"], correct: 2, explanation: "There are infinitely many rational numbers between any two distinct rational numbers, which can be found by repeatedly taking the average of the two numbers." },
			{ chapter: "Ch 1: Number System", question: "The product of a non-zero rational number and an irrational number is:", options: ["Always irrational", "Always rational", "Sometimes rational, sometimes irrational", "An integer"], correct: 0, explanation: "Multiplying any non-zero rational number by an irrational number always yields an irrational result." },
			{ chapter: "Ch 1: Number System", question: "The value of 1.999... in the form p/q, where p and q are integers and q ≠ 0, is:", options: ["19/10", "199/100", "2", "1/9"], correct: 2, explanation: "Let x = 1.999... Then 10x = 19.999... Subtracting x from 10x gives 9x = 18, which means x = 2." },
			{ chapter: "Ch 1: Number System", question: "What is the rationalising factor of 1 / (√5 - √2)?", options: ["√5 + √2", "√5 - √2", "5 + 2", "3"], correct: 0, explanation: "To rationalise the denominator, you multiply the numerator and denominator by the conjugate, which reverses the sign: (√5 + √2)." },
			{ chapter: "Ch 1: Number System", question: "The value of 32^(1/5) is:", options: ["2", "4", "8", "16"], correct: 0, explanation: "Since 2 × 2 × 2 × 2 × 2 = 32, the 5th root of 32 is 2." },
			{ chapter: "Ch 1: Number System", question: "Which of the following is NOT a rational number?", options: ["√9", "√16", "√24", "√25"], correct: 2, explanation: "24 is not a perfect square, so √24 cannot be expressed as an exact fraction p/q, making it irrational." },
			{ chapter: "Ch 1: Number System", question: "The decimal expansion of an irrational number is always:", options: ["Terminating", "Non-terminating repeating", "Non-terminating non-repeating", "None of these"], correct: 2, explanation: "Irrational numbers have chaotic, endless decimal expansions that never settle into a repeating pattern." },
			{ chapter: "Ch 1: Number System", question: "A rational number strictly between 1/2 and 1/3 is:", options: ["5/12", "1/5", "1/6", "1/4"], correct: 0, explanation: "To find a number exactly halfway between them, average them: (1/2 + 1/3) / 2 = (5/6) / 2 = 5/12." },
			{ chapter: "Ch 1: Number System", question: "The value of (64)^(-1/2) is:", options: ["8", "1/8", "-8", "-1/8"], correct: 1, explanation: "The negative exponent flips the base to the denominator (1/64), and the 1/2 exponent represents the square root. The square root of 1/64 is 1/8." },
			{ chapter: "Ch 1: Number System", question: "Which of the following numbers is definitively rational?", options: ["√2", "π", "√225", "√23"], correct: 2, explanation: "225 is a perfect square. √225 exactly equals 15, which is a rational integer." },
			{ chapter: "Ch 1: Number System", question: "The sum of two irrational numbers is:", options: ["Always irrational", "Always rational", "Sometimes rational, sometimes irrational", "Zero"], correct: 2, explanation: "If you add √2 and -√2 (both irrational), the sum is 0 (rational). If you add √2 and √3, the sum is irrational." },
			{ chapter: "Ch 1: Number System", question: "The decimal expansion of the rational number 1/3 is:", options: ["Terminating", "Non-terminating and repeating", "Non-terminating and non-repeating", "None of these"], correct: 1, explanation: "1 divided by 3 equals 0.3333..., which goes on forever but repeats a distinct pattern." },
			{ chapter: "Ch 1: Number System", question: "Which of the following is equal to x?", options: ["x^(12/7) - x^(5/7)", "12th root of (x^4)^(1/3)", "(x^3)^(1/3)", "x^(12/7) × x^(7/12)"], correct: 2, explanation: "(x^3)^(1/3) means the exponents multiply: 3 × 1/3 = 1, leaving just x." },
			{ chapter: "Ch 1: Number System", question: "The number 1.101001000100001... is:", options: ["Rational", "Irrational", "An Integer", "A whole number"], correct: 1, explanation: "The pattern does not repeat exactly (the zeros increase), making it non-terminating and non-repeating." },
			{ chapter: "Ch 1: Number System", question: "What is the rationalising factor of 1 / √7?", options: ["1/7", "7", "√7", "-√7"], correct: 2, explanation: "Multiplying numerator and denominator by √7 clears the square root from the denominator." },
			{ chapter: "Ch 1: Number System", question: "If x = 2 + √3, then the value of x + 1/x is:", options: ["4", "2√3", "4 + 2√3", "0"], correct: 0, explanation: "1/x = 1/(2+√3) which rationalises to 2-√3. So, (2+√3) + (2-√3) = 4." },
			{ chapter: "Ch 1: Number System", question: "The value of 7^(1/2) × 8^(1/2) is:", options: ["56^(1/2)", "15^(1/2)", "56", "15"], correct: 0, explanation: "When exponents are the same, bases multiply: (7 × 8)^(1/2) = 56^(1/2)." },
			{ chapter: "Ch 1: Number System", question: "An irrational number between √2 and √3 is:", options: ["1.5", "√(√2 × √3)", "√5", "1.7"], correct: 1, explanation: "The square root of the product of two irrational numbers provides an irrational number geometrically between them." },
			
            // Chapter 2: Polynomials
            { chapter: "Ch 2: Polynomials", question: "What is the degree of a non-zero constant polynomial?", options: ["0", "1", "Any natural number", "Not defined"], correct: 0, explanation: "A non-zero constant (like 5) can be written as 5x^0. Therefore, the highest power of the variable (degree) is 0." },
            { chapter: "Ch 2: Polynomials", question: "If p(x) = x + 3, then p(x) + p(-x) is equal to:", options: ["3", "2x", "0", "6"], correct: 3, explanation: "p(x) = x + 3. p(-x) = -x + 3. Adding them: (x + 3) + (-x + 3) = 6." },
            { chapter: "Ch 2: Polynomials", question: "The coefficient of x in the expansion of (x + 3)³ is:", options: ["1", "9", "18", "27"], correct: 3, explanation: "Using the identity (a + b)³ = a³ + b³ + 3a²b + 3ab², the expansion is x³ + 27 + 9x² + 27x. The coefficient attached to x is 27." },
			{ chapter: "Ch 2: Polynomials", question: "Which of the following is a binomial?", options: ["2x", "x² + 5x - 6", "x² + 4", "5"], correct: 2, explanation: "A binomial is a polynomial with exactly two non-zero terms. 'x² + 4' has two terms." },
			{ chapter: "Ch 2: Polynomials", question: "The degree of the zero polynomial is:", options: ["0", "1", "Any real number", "Not defined"], correct: 3, explanation: "The zero polynomial is just the number 0. Since 0 can be written as 0x⁰, 0x¹, 0x¹⁰⁰, etc., its degree is not defined." },
			{ chapter: "Ch 2: Polynomials", question: "If (x + 1) is a factor of p(x) = x² + kx + 2, then the value of k is:", options: ["2", "3", "-3", "-2"], correct: 1, explanation: "By the Factor Theorem, p(-1) = 0. Therefore, (-1)² + k(-1) + 2 = 0 ➔ 1 - k + 2 = 0 ➔ 3 - k = 0 ➔ k = 3." },
			{ chapter: "Ch 2: Polynomials", question: "The value of k, if (x - 1) is a factor of 4x³ + 3x² - 4x + k, is:", options: ["1", "2", "-3", "3"], correct: 2, explanation: "By the Factor Theorem, p(1) = 0. So, 4(1)³ + 3(1)² - 4(1) + k = 0 ➔ 4 + 3 - 4 + k = 0 ➔ 3 + k = 0 ➔ k = -3." },
			{ chapter: "Ch 2: Polynomials", question: "One of the factors of (25x² - 1) + (1 + 5x)² is:", options: ["5x - 1", "10x", "5x + 1", "10x - 1"], correct: 2, explanation: "Factorise the first part using a²-b²: (5x - 1)(5x + 1) + (5x + 1)². Taking (5x + 1) common gives (5x + 1)[(5x - 1) + (5x + 1)] = (5x + 1)(10x)." },
			{ chapter: "Ch 2: Polynomials", question: "What is the remainder when x³ + 3x² + 3x + 1 is divided by (x + 1)?", options: ["0", "1", "2", "3"], correct: 0, explanation: "Using the Remainder Theorem, plug in x = -1: (-1)³ + 3(-1)² + 3(-1) + 1 = -1 + 3 - 3 + 1 = 0." },
			{ chapter: "Ch 2: Polynomials", question: "The value of the polynomial p(x) = 5x - 4x² + 3 at x = 0 is:", options: ["3", "5", "-4", "0"], correct: 0, explanation: "Substitute x = 0 into the polynomial: 5(0) - 4(0)² + 3 = 0 - 0 + 3 = 3." },
			{ chapter: "Ch 2: Polynomials", question: "The degree of the polynomial 4x⁴ + 0x⁵ + 5x + 7 is:", options: ["4", "5", "1", "0"], correct: 0, explanation: "The term with x⁵ is multiplied by zero, removing it. The highest remaining power is 4." },
			{ chapter: "Ch 2: Polynomials", question: "The expanded form of (x + y + z)² is:", options: ["x² + y² + z²", "x² + y² + z² + 2xy + 2yz + 2zx", "x² + y² + z² + xyz", "x² + y² + z² + 3xyz"], correct: 1, explanation: "This is a standard algebraic identity: (x + y + z)² exactly equals x² + y² + z² + 2xy + 2yz + 2zx." },
			{ chapter: "Ch 2: Polynomials", question: "The zero of the linear polynomial p(x) = cx + d (where c ≠ 0) is:", options: ["d/c", "-d/c", "-c/d", "c/d"], correct: 1, explanation: "To find the zero, set p(x) = 0. Therefore, cx + d = 0 ➔ cx = -d ➔ x = -d/c." },
			{ chapter: "Ch 2: Polynomials", question: "The factorization of (x² - y²/100) is:", options: ["(x - y/10)²", "(x + y/10)²", "(x - y/10)(x + y/10)", "(x - y)(x + y)/100"], correct: 2, explanation: "This takes the form of the identity a² - b² = (a - b)(a + b). Here, a = x and b = y/10." },
			{ chapter: "Ch 2: Polynomials", question: "What is the degree of a standard quadratic polynomial?", options: ["1", "2", "3", "0"], correct: 1, explanation: "A quadratic polynomial (like ax² + bx + c) always has a highest exponent (degree) of exactly 2." },
			{ chapter: "Ch 2: Polynomials", question: "Using an algebraic identity, the value of 104 × 96 is:", options: ["9984", "10000", "9964", "9996"], correct: 0, explanation: "Rewrite as (100 + 4)(100 - 4). Using a² - b², this becomes 100² - 4² = 10000 - 16 = 9984." },
			{ chapter: "Ch 2: Polynomials", question: "If p(x) = x^2 - 2√2x + 1, then p(2√2) is:", options: ["0", "1", "4√2", "8"], correct: 1, explanation: "Substitute x: (2√2)^2 - 2√2(2√2) + 1 = 8 - 8 + 1 = 1." },
			{ chapter: "Ch 2: Polynomials", question: "The factorization of 4x^2 + 8x + 3 is:", options: ["(2x+1)(2x+3)", "(2x-1)(2x-3)", "(2x+2)(2x+1.5)", "(4x+1)(x+3)"], correct: 0, explanation: "Split middle term 8x into 2x + 6x. Grouping yields (2x+1)(2x+3)." },
			{ chapter: "Ch 2: Polynomials", question: "If x + 1 is a factor of x^3 + kx^2 - 2x + 1, then k is:", options: ["-4", "4", "2", "-2"], correct: 0, explanation: "By factor theorem, p(-1)=0. (-1)^3 + k(-1)^2 - 2(-1) + 1 = 0 ➔ -1 + k + 2 + 1 = 0 ➔ k = -4." },
			{ chapter: "Ch 2: Polynomials", question: "Zero of the polynomial p(x) = ax + b (a ≠ 0) is:", options: ["b/a", "a/b", "-b/a", "-a/b"], correct: 2, explanation: "Set ax + b = 0, which solves to x = -b/a." },
			{ chapter: "Ch 2: Polynomials", question: "The coefficient of x^2 in (3x - 5)(2x + 3) is:", options: ["6", "-1", "-6", "5"], correct: 0, explanation: "Multiply out: 6x^2 + 9x - 10x - 15 = 6x^2 - x - 15. The x^2 coefficient is 6." },
			{ chapter: "Ch 2: Polynomials", question: "Which of the following is a cubic polynomial?", options: ["x^3 + 3x", "x^2 + 3x", "x^4 - 1", "3x + 1"], correct: 0, explanation: "A cubic polynomial has a highest degree of 3." },
			{ chapter: "Ch 2: Polynomials", question: "If x^2 + 1/x^2 = 23, then x + 1/x is:", options: ["25", "5", "√23", "4"], correct: 1, explanation: "(x + 1/x)^2 = x^2 + 1/x^2 + 2 = 23 + 2 = 25. Thus, x + 1/x = 5." },

            // Chapter 3: Coordinate Geometry
            { chapter: "Ch 3: Coordinate Geometry", question: "The perpendicular distance of the point P(3, 4) from the y-axis is:", options: ["3", "4", "5", "7"], correct: 0, explanation: "The distance of a point from the y-axis is given by its x-coordinate (abscissa). Here, the x-coordinate is 3." },
            { chapter: "Ch 3: Coordinate Geometry", question: "Signs of the abscissa and ordinate of a point in the third quadrant are respectively:", options: ["(+, +)", "(-, +)", "(+, -)", "(-, -)"], correct: 3, explanation: "In the third quadrant, you move left on the x-axis (negative) and down on the y-axis (negative), resulting in (-, -)." },
            { chapter: "Ch 3: Coordinate Geometry", question: "The point at which the two coordinate axes meet is called the:", options: ["Abscissa", "Ordinate", "Origin", "Quadrant"], correct: 2, explanation: "The x-axis and y-axis intersect at the point (0,0), which is universally known as the Origin." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The abscissa of all points on the y-axis is:", options: ["0", "1", "2", "Any number"], correct: 0, explanation: "The abscissa is the x-coordinate. For any point lying directly on the vertical y-axis, its horizontal distance (x-coordinate) is strictly 0." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "A point whose abscissa is 2 and ordinate is -5 lies in the:", options: ["First Quadrant", "Second Quadrant", "Third Quadrant", "Fourth Quadrant"], correct: 3, explanation: "The point is (2, -5). The x-value is positive and the y-value is negative, which corresponds to the Fourth Quadrant." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The perpendicular distance of the point P(4, 3) from the x-axis is:", options: ["4", "3", "5", "None of these"], correct: 1, explanation: "The distance from the x-axis is measured vertically, which is exactly the y-coordinate (ordinate) of the point. Thus, it is 3." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The point (-3, -4) lies in which quadrant?", options: ["First", "Second", "Third", "Fourth"], correct: 2, explanation: "Both the x-coordinate and the y-coordinate are negative, which places the point squarely in the Third Quadrant." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The mirror image of the point (3, 4) across the x-axis is:", options: ["(-3, 4)", "(3, -4)", "(-3, -4)", "(4, 3)"], correct: 1, explanation: "Reflecting a point vertically across the x-axis flips the sign of its y-coordinate while keeping the x-coordinate the same." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The distance of the point (0, -5) from the origin is:", options: ["0 units", "5 units", "-5 units", "25 units"], correct: 1, explanation: "Distance represents a physical length, which is always positive. The point is exactly 5 units straight down from the origin." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "A point where both coordinates are negative lies in which quadrant?", options: ["First", "Second", "Third", "Fourth"], correct: 2, explanation: "Moving left on the x-axis (negative) and down on the y-axis (negative) places you in the Third Quadrant." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The ordinate of any point resting exactly on the x-axis is:", options: ["1", "0", "x", "Any number"], correct: 1, explanation: "The ordinate is the y-coordinate. If a point is on the x-axis, it hasn't moved up or down, so its y-value is 0." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "A point lying on the x-axis at a distance of 5 units to the right of the origin has the coordinates:", options: ["(0, 5)", "(5, 0)", "(-5, 0)", "(0, -5)"], correct: 1, explanation: "On the x-axis, the y-coordinate is always 0. Moving 5 units to the right gives an x-value of +5." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The exact coordinates of the mathematical origin are:", options: ["(1, 1)", "(0, 1)", "(1, 0)", "(0, 0)"], correct: 3, explanation: "The origin is the starting reference point where the x-axis and y-axis intersect, defined as (0, 0)." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "If a point's coordinates have the signs (-, +), it must lie in the:", options: ["First Quadrant", "Second Quadrant", "Third Quadrant", "Fourth Quadrant"], correct: 1, explanation: "A negative x-value (left) and positive y-value (up) always maps to the Second Quadrant." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The perpendicular distance of the point (5, 12) from the y-axis is:", options: ["5 units", "12 units", "13 units", "17 units"], correct: 0, explanation: "The distance from the vertical y-axis is defined by how far left or right the point is, which is its x-coordinate (5)." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The coordinate axes divide the plane into how many parts?", options: ["2", "3", "4", "8"], correct: 2, explanation: "The intersecting x and y axes divide the 2D plane into four quadrants." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "If the coordinates of points A and B are (-2, 5) and (3, 5), then the line AB is:", options: ["Parallel to x-axis", "Parallel to y-axis", "Passing through origin", "None"], correct: 0, explanation: "Since the y-coordinates are exactly the same (5), the line has no slope and is parallel to the x-axis." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The distance of point P(3, -4) from the x-axis is:", options: ["3", "-4", "4", "5"], correct: 2, explanation: "Distance is always positive. The distance from the x-axis is the absolute value of the y-coordinate, which is 4." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "A point lies on the negative side of the y-axis at a distance of 3 units from the origin. Its coordinates are:", options: ["(0, 3)", "(3, 0)", "(0, -3)", "(-3, 0)"], correct: 2, explanation: "On the y-axis, x=0. Negative side means moving down by 3, so (0, -3)." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The point of intersection of the coordinate axes is called:", options: ["Abscissa", "Ordinate", "Origin", "Quadrant"], correct: 2, explanation: "The origin is the center point (0,0) where axes cross." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "Signs of coordinates in the second quadrant are:", options: ["(+,+)", "(-,+)", "(-,-)", "(+,-)"], correct: 1, explanation: "In the 2nd quadrant, x is negative (left) and y is positive (up)." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "If abscissa of a point is zero, the point lies on:", options: ["x-axis", "y-axis", "Origin only", "First quadrant"], correct: 1, explanation: "Abscissa is the x-value. If x=0, the point must be somewhere on the vertical y-axis." },

            // Chapter 4: Linear Equations in Two Variables
            { chapter: "Ch 4: Linear Equations", question: "The linear equation 2x - 5y = 7 has:", options: ["A unique solution", "Two solutions", "Infinitely many solutions", "No solution"], correct: 2, explanation: "A linear equation in two variables represents a straight line. Since a line consists of infinite points, the equation has infinitely many solutions." },
            { chapter: "Ch 4: Linear Equations", question: "The equation of x-axis is of the form:", options: ["x = 0", "y = 0", "x + y = 0", "x = y"], correct: 1, explanation: "On the x-axis, the vertical distance from the origin is always zero. Therefore, the y-coordinate for every point on the x-axis is 0 (y = 0)." },
            { chapter: "Ch 4: Linear Equations", question: "The graph of the linear equation 2x + 3y = 6 cuts the y-axis at the point:", options: ["(2, 0)", "(0, 3)", "(3, 0)", "(0, 2)"], correct: 3, explanation: "To find where a line cuts the y-axis, the x-coordinate must be 0. Set x = 0: 2(0) + 3y = 6 ➔ 3y = 6 ➔ y = 2. The point is (0, 2)." },
			{ chapter: "Ch 4: Linear Equations", question: "The equation y = 5, written in standard two-variable form (ax + by + c = 0), is:", options: ["1x + 1y - 5 = 0", "0x + 1y - 5 = 0", "1x + 0y - 5 = 0", "0x + 0y - 5 = 0"], correct: 1, explanation: "Since there is no x term, its coefficient 'a' must be 0. So it is written as 0x + 1y - 5 = 0." },
			{ chapter: "Ch 4: Linear Equations", question: "Any point on the line x = y is of the form:", options: ["(k, -k)", "(0, k)", "(k, 0)", "(k, k)"], correct: 3, explanation: "Because the equation is x = y, the x-coordinate and y-coordinate of any point on this line must be exactly identical." },
			{ chapter: "Ch 4: Linear Equations", question: "How many linear equations in x and y can be satisfied by x = 1 and y = 2?", options: ["Only one", "Two", "Infinitely many", "Three"], correct: 2, explanation: "The point (1, 2) represents a single point on a graph. Infinite unique lines can intersect and pass through a single point." },
			{ chapter: "Ch 4: Linear Equations", question: "The graph of the equation x = 4 is a straight line:", options: ["Parallel to the x-axis", "Parallel to the y-axis", "Passing through the origin", "Intersecting both axes"], correct: 1, explanation: "The equation x = 4 means that x is always 4 regardless of the y-value. This creates a vertical line that is parallel to the y-axis." },
			{ chapter: "Ch 4: Linear Equations", question: "The equation of a line passing straight through the origin is always of the form:", options: ["x + y = 1", "y = mx", "y = c", "x = c"], correct: 1, explanation: "For a line to cross the origin (0,0), it cannot have a stray constant (y-intercept). y = mx guarantees that when x=0, y=0." },
			{ chapter: "Ch 4: Linear Equations", question: "How many total solutions exist for the equation y = 3x + 5?", options: ["1", "2", "3", "Infinitely many"], correct: 3, explanation: "A linear equation in two variables represents a continuous line, which is made up of an infinite number of coordinate points." },
			{ chapter: "Ch 4: Linear Equations", question: "Which equation has x = 2 and y = -1 as a valid solution?", options: ["2x + y = 0", "x + 2y = 0", "x + y = 0", "2x - y = 0"], correct: 1, explanation: "Plug the values into x + 2y = 0: (2) + 2(-1) = 2 - 2 = 0." },
			{ chapter: "Ch 4: Linear Equations", question: "The graph of y = 6 is a straight line that is:", options: ["Parallel to the x-axis", "Parallel to the y-axis", "Passing through origin", "Intersecting both axes"], correct: 0, explanation: "y = 6 means the height is locked at 6 regardless of x, creating a horizontal line parallel to the x-axis." },
			{ chapter: "Ch 4: Linear Equations", question: "The equation of any line parallel to the x-axis takes the form:", options: ["x = c", "y = c", "y = mx", "x + y = c"], correct: 1, explanation: "A line parallel to the x-axis is perfectly horizontal, meaning its height (y) is locked at a constant value 'c' regardless of x." },
			{ chapter: "Ch 4: Linear Equations", question: "Which point represents the intersection of the line x + y = 5 with the y-axis?", options: ["(5, 0)", "(0, 5)", "(2.5, 2.5)", "(0, 0)"], correct: 1, explanation: "At the y-axis intersection, x is 0. Plugging x = 0 into the equation gives 0 + y = 5, meaning the point is (0, 5)." },
			{ chapter: "Ch 4: Linear Equations", question: "For the equation ax + by + c = 0 to represent a linear equation in two variables, the condition is:", options: ["a = 0, b = 0", "a ≠ 0 and b ≠ 0", "c = 0", "a = b"], correct: 1, explanation: "If both 'a' and 'b' were 0, the variables would disappear entirely. Both coefficients cannot be zero simultaneously." },
			{ chapter: "Ch 4: Linear Equations", question: "The graph of the equation y = x will always pass through:", options: ["(1, 0)", "(0, 1)", "(0, 0)", "(-1, 0)"], correct: 2, explanation: "If you set x = 0, y must also equal 0. Therefore, the line must pass directly through the origin (0,0)." },
			{ chapter: "Ch 4: Linear Equations", question: "The equation x - 2 = 0 on a number line is represented by:", options: ["A point", "A line", "A plane", "A ray"], correct: 0, explanation: "On a single 1D number line, a single value x=2 is just a singular dot (point)." },
			{ chapter: "Ch 4: Linear Equations", question: "The equation x - 2 = 0 on a Cartesian plane is represented by:", options: ["A point", "A line parallel to y-axis", "A line parallel to x-axis", "A line passing through origin"], correct: 1, explanation: "In 2D, x=2 means x is always 2 regardless of y, forming a vertical line parallel to the y-axis." },
			{ chapter: "Ch 4: Linear Equations", question: "If (2, 0) is a solution of the linear equation 2x + 3y = k, then the value of k is:", options: ["4", "5", "6", "2"], correct: 0, explanation: "Plug in x=2, y=0: 2(2) + 3(0) = k ➔ 4 = k." },
			{ chapter: "Ch 4: Linear Equations", question: "The graph of the linear equation 2x - y = 4 cuts the x-axis at:", options: ["(2, 0)", "(0, -4)", "(0, 2)", "(4, 0)"], correct: 0, explanation: "At the x-axis, y=0. So 2x - 0 = 4 ➔ x = 2. Point is (2,0)." },
			{ chapter: "Ch 4: Linear Equations", question: "Which of the following is not a linear equation in two variables?", options: ["ax + by = c", "x = y", "x^2 + y = 1", "y = 5"], correct: 2, explanation: "x^2 has a degree of 2, making it a quadratic equation, not linear." },
			{ chapter: "Ch 4: Linear Equations", question: "The linear equation 3x = 2y can be written as:", options: ["3x - 2y = 0", "3x + 2y = 0", "2x - 3y = 0", "2y - 3x = 0"], correct: 0, explanation: "Bring 2y to the left side by subtracting it: 3x - 2y = 0." },
			{ chapter: "Ch 4: Linear Equations", question: "How many lines can pass through a given point?", options: ["One", "Two", "Three", "Infinitely many"], correct: 3, explanation: "A single coordinate point can act as a pivot for an infinite number of intersecting lines." },

            // Chapter 5: Introduction to Euclid's Geometry
            { chapter: "Ch 5: Euclidean Geometry", question: "According to Euclid's axioms, if equals are subtracted from equals, the remainders are:", options: ["Proportional", "Unequal", "Equal", "Zero"], correct: 2, explanation: "This is Euclid's Third Axiom. If A = B and C = D, then A - C = B - D." },
            { chapter: "Ch 5: Euclidean Geometry", question: "According to Euclidean geometry, a solid shape has:", options: ["1 dimension", "2 dimensions", "3 dimensions", "No dimensions"], correct: 2, explanation: "A solid possesses length, breadth, and height/depth, making it a 3-dimensional object." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "In Euclid's definitions, a point is defined as having:", options: ["1 dimension", "2 dimensions", "3 dimensions", "No part (zero dimensions)"], correct: 3, explanation: "Euclid's very first definition states: 'A point is that which has no part', meaning it has zero dimensions (no length, width, or depth)." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "The boundaries of a surface are:", options: ["Surfaces", "Curves", "Lines", "Points"], correct: 2, explanation: "Euclid stated that the extremities or boundaries of a 2D surface are 1D lines." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "Euclid's second axiom states: If equals are added to equals, the wholes are:", options: ["Unequal", "Equal", "Doubled", "Zero"], correct: 1, explanation: "If you have two equal quantities and add the same amount to both, the final sums must also be perfectly equal." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "According to Euclidean definitions, a simple surface has:", options: ["Length only", "Length and breadth only", "Length, breadth, and thickness", "No dimensions"], correct: 1, explanation: "A surface is a 2D mathematical object. It has length and breadth, but no physical thickness." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "How many distinct straight lines can pass through exactly two given points?", options: ["Infinite", "One and only one", "Two", "Zero"], correct: 1, explanation: "Euclid's first postulate establishes that a unique straight line can be drawn from any one point to any other point." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "The extremities (boundaries) of a 3D solid are:", options: ["Points", "Lines", "Surfaces", "Angles"], correct: 2, explanation: "The outer shell or boundary of a 3-dimensional solid object is made up of 2-dimensional surfaces (faces)." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "According to Euclid, things which coincide with one another are:", options: ["Unequal", "Double of one another", "Equal to one another", "Halves of one another"], correct: 2, explanation: "Axiom 4 states that if two figures can be superimposed perfectly on top of each other, they are equal." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "Euclid belongs to the country:", options: ["Greece", "Egypt", "Italy", "India"], correct: 0, explanation: "Euclid was an ancient Greek mathematician, often referred to as the 'founder of geometry'." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "The number of interwoven isosceles triangles in Sriyantra is:", options: ["7", "8", "9", "11"], correct: 2, explanation: "The Sriyantra consists of 9 interwoven isosceles triangles." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "Which of the following needs a proof?", options: ["Axiom", "Theorem", "Postulate", "Definition"], correct: 1, explanation: "Axioms and postulates are assumed true. Theorems are statements that must be proven using logic." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "A pyramid is a solid figure whose base is:", options: ["Only a triangle", "Only a square", "Only a rectangle", "Any polygon"], correct: 3, explanation: "A pyramid can have a triangular, square, pentagonal, or any polygonal base." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "The things which are double of the same thing are:", options: ["Equal", "Unequal", "Halves", "Triples"], correct: 0, explanation: "Axiom: If A = X and B = X, then 2A = 2X and 2B = 2X, making 2A = 2B." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "A surface has dimensions:", options: ["0", "1", "2", "3"], correct: 2, explanation: "A mathematical surface has only length and breadth (2 dimensions)." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "Boundaries of solids are:", options: ["Surfaces", "Curves", "Lines", "Points"], correct: 0, explanation: "The outer shell of a 3D solid is made of 2D surfaces (faces)." },

            // Chapter 6: Lines and Angles
            { chapter: "Ch 6: Lines & Angles", question: "An angle is 20° more than its complement. What is its measure?", options: ["35°", "55°", "70°", "110°"], correct: 1, explanation: "Let the angle be x. Its complement is (90 - x). The equation is x = (90 - x) + 20. Solving gives 2x = 110, so x = 55°." },
            { chapter: "Ch 6: Lines & Angles", question: "If two interior angles on the same side of a transversal intersecting two parallel lines are in the ratio 2:3, then the greater of the two angles is:", options: ["54°", "108°", "120°", "136°"], correct: 1, explanation: "Co-interior angles sum to 180°. Let them be 2x and 3x. 5x = 180° -> x = 36°. The greater angle is 3x = 3(36°) = 108°." },
            { chapter: "Ch 6: Lines & Angles", question: "If two complementary angles are in the ratio 13:5, then the angles are:", options: ["13°, 5°", "65°, 25°", "25°, 65°", "65°, 35°"], correct: 1, explanation: "Complementary angles add to 90°. Let the angles be 13x and 5x. 13x + 5x = 90° ➔ 18x = 90° ➔ x = 5. The angles are 13(5) = 65° and 5(5) = 25°." },
			{ chapter: "Ch 6: Lines & Angles", question: "If two lines intersect, the vertically opposite angles are:", options: ["Complementary", "Supplementary", "Always Equal", "Unequal"], correct: 2, explanation: "A fundamental geometric theorem proves that when two lines intersect, the angles directly opposite each other at the vertex are always equal." },
			{ chapter: "Ch 6: Lines & Angles", question: "If one angle of a triangle is equal to the sum of the other two, the triangle must be:", options: ["Isosceles", "Obtuse", "Right-angled", "Equilateral"], correct: 2, explanation: "Let angles be A, B, C. If A = B + C, and we know A + B + C = 180°, then A + A = 180°, meaning A = 90°." },
			{ chapter: "Ch 6: Lines & Angles", question: "The sum of the interior angles of any triangle is exactly:", options: ["90°", "180°", "270°", "360°"], correct: 1, explanation: "The angle sum property of triangles states that the interior angles always add up to exactly 180°." },
			{ chapter: "Ch 6: Lines & Angles", question: "An exterior angle of a triangle is 105° and its two interior opposite angles are equal. Each of these equal angles is:", options: ["37.5°", "52.5°", "72.5°", "75°"], correct: 1, explanation: "The Exterior Angle Theorem states the exterior angle equals the sum of the two opposite interior angles. So, 2x = 105° ➔ x = 52.5°." },
			{ chapter: "Ch 6: Lines & Angles", question: "Two complementary angles are such that one is exactly double the other. The angles are:", options: ["30° and 60°", "45° and 45°", "20° and 70°", "40° and 50°"], correct: 0, explanation: "Complementary angles sum to 90°. Let them be x and 2x. 3x = 90° ➔ x = 30°. The angles are 30° and 60°." },
			{ chapter: "Ch 6: Lines & Angles", question: "An angle which is exactly equal to its own supplement is:", options: ["45°", "90°", "180°", "60°"], correct: 1, explanation: "Supplementary angles add to 180°. If x = 180 - x, then 2x = 180, meaning x = 90°." },
			{ chapter: "Ch 6: Lines & Angles", question: "If two parallel lines are cut by a transversal, the alternate interior angles are always:", options: ["Equal", "Supplementary", "Complementary", "Acute"], correct: 0, explanation: "This is a core theorem: Alternate interior angles forming a 'Z' shape between parallel lines are always identical." },
			{ chapter: "Ch 6: Lines & Angles", question: "By geometric definition, an acute angle is an angle that measures:", options: ["Greater than 90°", "Strictly less than 90°", "Exactly 90°", "Exactly 180°"], correct: 1, explanation: "An acute angle is any angle larger than 0° but smaller than a 90° right angle." },
			{ chapter: "Ch 6: Lines & Angles", question: "The sum of all angles formed around a single central point is always:", options: ["90°", "180°", "270°", "360°"], correct: 3, explanation: "Angles completing a full circle around a single point will always add up to exactly 360°." },
			{ chapter: "Ch 6: Lines & Angles", question: "An angle that measures exactly 180° is formally called a:", options: ["Right angle", "Straight angle", "Reflex angle", "Obtuse angle"], correct: 1, explanation: "A 180° angle creates a perfectly flat line, which is why it is known as a straight angle." },
			{ chapter: "Ch 6: Lines & Angles", question: "When a transversal cuts two parallel lines, the corresponding angles are:", options: ["Complementary", "Supplementary", "Always Equal", "Unequal"], correct: 2, explanation: "Corresponding angles sit in the same relative position at each intersection, and they are always equal when lines are parallel." },
			{ chapter: "Ch 6: Lines & Angles", question: "An angle whose measure is greater than 180° but less than 360° is called a:", options: ["Obtuse angle", "Acute angle", "Straight angle", "Reflex angle"], correct: 3, explanation: "A reflex angle \"bends backward\" past a straight line, existing anywhere between 180° and a full 360° rotation." },
			{ chapter: "Ch 6: Lines & Angles", question: "If the angles of a triangle are in the ratio 2:3:4, the largest angle is:", options: ["40°", "60°", "80°", "100°"], correct: 2, explanation: "2x + 3x + 4x = 180° ➔ 9x = 180° ➔ x = 20°. Largest angle is 4(20°) = 80°." },
			{ chapter: "Ch 6: Lines & Angles", question: "If a transversal intersects two parallel lines, then consecutive interior angles are:", options: ["Equal", "Complementary", "Supplementary", "None of these"], correct: 2, explanation: "Consecutive (co-interior) angles between parallel lines always add up to 180° (supplementary)." },
			{ chapter: "Ch 6: Lines & Angles", question: "In a triangle, an exterior angle is 110° and one of the interior opposite angles is 30°. The other is:", options: ["80°", "70°", "40°", "110°"], correct: 0, explanation: "Exterior angle = sum of interior opposite angles. 110° = 30° + x ➔ x = 80°." },
			{ chapter: "Ch 6: Lines & Angles", question: "The measure of an angle is 5 times its supplement. The angle is:", options: ["30°", "60°", "120°", "150°"], correct: 3, explanation: "x = 5(180 - x) ➔ x = 900 - 5x ➔ 6x = 900 ➔ x = 150°." },
			{ chapter: "Ch 6: Lines & Angles", question: "Two lines perpendicular to the same line are:", options: ["Perpendicular to each other", "Parallel to each other", "Intersecting", "Coincident"], correct: 1, explanation: "If two separate lines hit a third line at 90°, they must run in the exact same direction, making them parallel." },
			{ chapter: "Ch 6: Lines & Angles", question: "If two lines intersect, the vertically opposite angles are:", options: ["Complementary", "Supplementary", "Equal", "Unequal"], correct: 2, explanation: "Vertically opposite angles at an intersection are always geometrically equal." },
			{ chapter: "Ch 6: Lines & Angles", question: "The sum of the angles of a quadrilateral is:", options: ["180°", "270°", "360°", "540°"], correct: 2, explanation: "A quadrilateral is formed by two triangles, so 2 × 180° = 360°." },

            // Chapter 7: Triangles
            { chapter: "Ch 7: Triangles", question: "Which of the following is NOT a criterion for congruence of triangles?", options: ["SAS", "ASA", "SSA", "SSS"], correct: 2, explanation: "SSA (Side-Side-Angle) is not a valid congruence criterion because it does not guarantee a unique triangle (the ambiguous case)." },
            { chapter: "Ch 7: Triangles", question: "In ΔABC, if AB = AC and ∠B = 50°, then ∠C is equal to:", options: ["40°", "50°", "80°", "130°"], correct: 1, explanation: "Angles opposite to equal sides of a triangle are equal. Since AB = AC, ∠C = ∠B = 50°." },
            { chapter: "Ch 7: Triangles", question: "In a right-angled triangle, the longest side is always the:", options: ["Base", "Perpendicular", "Hypotenuse", "Median"], correct: 2, explanation: "The hypotenuse is the side opposite to the right angle (90°), which is the largest angle in a right triangle, making it the longest side." },
			{ chapter: "Ch 7: Triangles", question: "If ΔABC ≅ ΔPQR, then which of the following is true?", options: ["AB = PQ", "AC = PQ", "BC = PR", "∠A = ∠R"], correct: 0, explanation: "By CPCTC (Corresponding Parts of Congruent Triangles are Congruent), the order matters. AB corresponds to PQ, BC to QR, and AC to PR." },
			{ chapter: "Ch 7: Triangles", question: "In ΔABC and ΔDEF, AB = FD and ∠A = ∠D. The two triangles will be congruent by the SAS axiom if:", options: ["BC = EF", "AC = DE", "AC = EF", "BC = DE"], correct: 1, explanation: "For SAS (Side-Angle-Side), the angle must be included between the two equal sides. Since we have side AB and angle A, the second side must be AC. Therefore, AC must equal DE." },
			{ chapter: "Ch 7: Triangles", question: "Angles opposite to equal sides of a triangle are:", options: ["Complementary", "Supplementary", "Always Equal", "Unequal"], correct: 2, explanation: "This is the isosceles triangle theorem: if two sides of a triangle are equal, the angles directly opposite those sides are also equal." },
			{ chapter: "Ch 7: Triangles", question: "If ΔABC ≅ ΔFDE and AB = 5cm, ∠B = 40° and ∠A = 80°, which of the following is true?", options: ["DF = 5cm, ∠F = 60°", "DF = 5cm, ∠E = 60°", "DE = 5cm, ∠E = 60°", "DE = 5cm, ∠D = 40°"], correct: 1, explanation: "Angle C = 180 - (80+40) = 60°. By corresponding parts (FDE), F corresponds to A(80°), D corresponds to B(40°), E corresponds to C(60°). AB(5cm) corresponds to FD(5cm)." },
			{ chapter: "Ch 7: Triangles", question: "Two sides of a triangle are of lengths 5 cm and 1.5 cm. The length of the third side cannot be:", options: ["3.6 cm", "4.1 cm", "3.8 cm", "3.4 cm"], correct: 3, explanation: "By the triangle inequality theorem, the difference of two sides must be less than the third side. 5 - 1.5 = 3.5. The third side must be greater than 3.5 cm." },
			{ chapter: "Ch 7: Triangles", question: "In ΔABC, if ∠A = 40° and ∠B = 60°, what is the longest side of the triangle?", options: ["AB", "BC", "AC", "All sides are equal"], correct: 0, explanation: "The angles sum to 180°, so ∠C = 80°. The longest side of a triangle is always directly opposite its largest angle. Therefore, AB is longest." },
			{ chapter: "Ch 7: Triangles", question: "If the median of a triangle is identical to its altitude, the triangle must be:", options: ["Scalene", "Right-angled", "Isosceles", "Obtuse"], correct: 2, explanation: "In an isosceles (or equilateral) triangle, the line drawn from the vertex to the midpoint of the unequal base also strikes it at exactly 90°." },
			{ chapter: "Ch 7: Triangles", question: "In ΔPQR, PQ = PR and ∠Q = 65°. What is the measure of ∠P?", options: ["65°", "50°", "115°", "40°"], correct: 1, explanation: "Since PQ = PR, the opposite angles are equal (∠R = 65°). Angles sum to 180°: ∠P = 180° - (65° + 65°) = 180° - 130° = 50°." },
			{ chapter: "Ch 7: Triangles", question: "The sum of the lengths of any two sides of a triangle is always:", options: ["Equal to the third side", "Less than the third side", "Greater than the third side", "Double the third side"], correct: 2, explanation: "This is the Triangle Inequality Theorem. A triangle cannot physically close if two sides are shorter than or equal to the base." },
			{ chapter: "Ch 7: Triangles", question: "Each interior angle of an equilateral triangle measures exactly:", options: ["45°", "60°", "90°", "120°"], correct: 1, explanation: "An equilateral triangle has three equal angles. Since they must sum to 180°, each angle is 180 / 3 = 60°." },
			{ chapter: "Ch 7: Triangles", question: "The RHS congruence criterion applies exclusively to which type of triangle?", options: ["Isosceles", "Equilateral", "Right-angled", "Scalene"], correct: 2, explanation: "RHS stands for Right-angle, Hypotenuse, Side, meaning it can only be used to prove congruence between right-angled triangles." },
			{ chapter: "Ch 7: Triangles", question: "In ΔABC, if AB = BC and ∠B = 70°, what is the measure of ∠A?", options: ["55°", "70°", "110°", "40°"], correct: 0, explanation: "Because AB = BC, it's an isosceles triangle where ∠A = ∠C. 180° - 70° = 110°. Since ∠A and ∠C share this equally, 110 / 2 = 55°." },
			{ chapter: "Ch 7: Triangles", question: "In the ASA congruence rule, what does the 'S' stand for?", options: ["Any side", "The longest side", "The included side", "The hypotenuse"], correct: 2, explanation: "ASA stands for Angle-Side-Angle. The side must be the specific one geometrically \"included\" between the two known angles." },
			{ chapter: "Ch 7: Triangles", question: "In ΔABC, if ∠A = ∠C, then which sides are equal?", options: ["AB = BC", "AC = BC", "AB = AC", "None"], correct: 0, explanation: "Sides opposite to equal angles are equal. Side opposite ∠A is BC, side opposite ∠C is AB." },
			{ chapter: "Ch 7: Triangles", question: "Which of the following is not a congruence rule?", options: ["ASA", "SAS", "AAA", "RHS"], correct: 2, explanation: "AAA (Angle-Angle-Angle) proves similarity (same shape), but not congruence (same size)." },
			{ chapter: "Ch 7: Triangles", question: "If ΔABC ≅ ΔPQR, then ∠B corresponds to:", options: ["∠P", "∠Q", "∠R", "None"], correct: 1, explanation: "Order matters in congruence statements. B is the second letter, so it corresponds to the second letter Q." },
			{ chapter: "Ch 7: Triangles", question: "In ΔPQR, if PQ > PR, then:", options: ["∠R > ∠Q", "∠Q > ∠R", "∠R = ∠Q", "None"], correct: 0, explanation: "The angle opposite the longer side is always larger. ∠R is opposite PQ, so ∠R > ∠Q." },
			{ chapter: "Ch 7: Triangles", question: "Can a triangle have two right angles?", options: ["Yes", "No", "Only if it is isosceles", "Only if scalene"], correct: 1, explanation: "Two right angles sum to 180°. A triangle must have a third angle, meaning the sum would exceed 180°, which is impossible." },
			{ chapter: "Ch 7: Triangles", question: "If the altitudes of a triangle are equal, then the triangle is:", options: ["Isosceles", "Equilateral", "Right-angled", "Obtuse"], correct: 1, explanation: "Only a perfectly symmetrical equilateral triangle has three identical altitudes." },
			{ chapter: "Ch 7: Triangles", question: "In right ΔABC, ∠B = 90°. Which is the longest side?", options: ["AB", "BC", "AC", "Can't say"], correct: 2, explanation: "The side opposite the 90° angle (the largest angle in a right triangle) is the hypotenuse AC." },

            // Chapter 8: Quadrilaterals
            { chapter: "Ch 8: Quadrilaterals", question: "If angles of a quadrilateral are in ratio 3:5:9:13, the largest angle is:", options: ["156°", "146°", "136°", "126°"], correct: 0, explanation: "The sum of angles in a quadrilateral is 360°. Let angles be 3x, 5x, 9x, 13x. 30x = 360° -> x = 12°. Largest angle is 13(12°) = 156°." },
            { chapter: "Ch 8: Quadrilaterals", question: "The figure formed by joining the mid-points of the sides of a quadrilateral ABCD, taken in order, is a:", options: ["Rectangle", "Parallelogram", "Square", "Rhombus"], correct: 1, explanation: "By the Mid-point theorem applied to the triangles formed by the diagonals, the resulting figure is always a parallelogram." },
            { chapter: "Ch 8: Quadrilaterals", question: "A quadrilateral whose all sides are equal and angles are equal to 90° is called a:", options: ["Rectangle", "Square", "Rhombus", "Kite"], correct: 1, explanation: "A square specifically has all four sides equal and all four interior angles as 90°." },
			{ chapter: "Ch 8: Quadrilaterals", question: "The sum of the interior angles of a quadrilateral is:", options: ["180°", "270°", "360°", "400°"], correct: 2, explanation: "A quadrilateral can be split into two triangles. Since each triangle's interior angles sum to 180°, 2 × 180° = 360°." },
			{ chapter: "Ch 8: Quadrilaterals", question: "A diagonal of a parallelogram divides it into two:", options: ["Similar triangles", "Congruent triangles", "Equilateral triangles", "Right triangles"], correct: 1, explanation: "A diagonal of a parallelogram forms two triangles that are identical in shape and size (congruent) by the SSS or ASA congruence rule." },
			{ chapter: "Ch 8: Quadrilaterals", question: "If the diagonals of a quadrilateral bisect each other exactly at right angles, it is a:", options: ["Trapezium", "Parallelogram", "Rectangle", "Rhombus"], correct: 3, explanation: "While a square's diagonals also meet these criteria, a rhombus is the foundational quadrilateral where diagonals bisect each other at 90° without requiring 90° interior angles." },
			{ chapter: "Ch 8: Quadrilaterals", question: "A quadrilateral is guaranteed to be a parallelogram if its opposite angles are:", options: ["Unequal", "Supplementary", "Equal", "Complementary"], correct: 2, explanation: "One of the specific theorems for parallelograms states that if both pairs of opposite angles in a quadrilateral are equal, it must be a parallelogram." },
			{ chapter: "Ch 8: Quadrilaterals", question: "ABCD is a rhombus such that ∠ACB = 40°. What is the measure of ∠ADB?", options: ["40°", "50°", "90°", "100°"], correct: 1, explanation: "Rhombus diagonals cross at 90°. In right ΔBOC, ∠O=90° and ∠C=40°, making ∠OBC=50°. ∠ADB is alternate interior to ∠OBC, so it's 50°." },
			{ chapter: "Ch 8: Quadrilaterals", question: "The diagonals of a square bisect each other at exactly:", options: ["30°", "45°", "60°", "90°"], correct: 3, explanation: "A square is a special type of rhombus, and the diagonals of all rhombuses intersect at perfect right angles (90°)." },
			{ chapter: "Ch 8: Quadrilaterals", question: "A quadrilateral with exactly one pair of parallel sides is defined as a:", options: ["Kite", "Trapezium", "Parallelogram", "Rectangle"], correct: 1, explanation: "A trapezium (or trapezoid) is explicitly defined by having one, and only one, set of parallel opposite sides." },
			{ chapter: "Ch 8: Quadrilaterals", question: "The quadrilateral formed by joining the midpoints of an isosceles trapezium is a:", options: ["Rectangle", "Rhombus", "Square", "Parallelogram"], correct: 1, explanation: "Because the diagonals of an isosceles trapezium are equal in length, the resulting midpoint-connected shape has all four sides equal, forming a rhombus." },
			{ chapter: "Ch 8: Quadrilaterals", question: "Any two consecutive interior angles of a parallelogram are always:", options: ["Complementary", "Supplementary", "Equal", "Reflexive"], correct: 1, explanation: "Consecutive angles in a parallelogram form co-interior angles between parallel lines, meaning they must add up to 180° (supplementary)." },
			{ chapter: "Ch 8: Quadrilaterals", question: "A quadrilateral with exactly two pairs of equal adjacent sides is called a:", options: ["Rhombus", "Rectangle", "Kite", "Trapezium"], correct: 2, explanation: "A kite is defined specifically by having its adjacent (touching) sides equal in length, forming a cross-shaped diagonal structure." },
			{ chapter: "Ch 8: Quadrilaterals", question: "If the non-parallel sides of a trapezium are equal in length, it is specifically called:", options: ["A parallelogram", "An isosceles trapezium", "A kite", "A rhombus"], correct: 1, explanation: "Much like an isosceles triangle has two equal legs, an isosceles trapezium has two equal non-parallel legs." },
			{ chapter: "Ch 8: Quadrilaterals", question: "All four interior angles of a rectangle measure exactly:", options: ["45°", "60°", "90°", "120°"], correct: 2, explanation: "A rectangle is a special parallelogram where every single vertex forms a perfect right angle (90°)." },
			{ chapter: "Ch 8: Quadrilaterals", question: "If the diagonals of a quadrilateral bisect each other, it must be a:", options: ["Trapezium", "Parallelogram", "Kite", "None of these"], correct: 1, explanation: "Mutual bisection of diagonals is a defining property of all parallelograms." },
			{ chapter: "Ch 8: Quadrilaterals", question: "The line segment joining the midpoints of two sides of a triangle is:", options: ["Half of the third side", "Double the third side", "Equal to the third side", "Perpendicular to the third side"], correct: 0, explanation: "By the Midpoint Theorem, this segment is parallel to and exactly half the length of the third side." },
			{ chapter: "Ch 8: Quadrilaterals", question: "Diagonals of a rectangle are:", options: ["Unequal and perpendicular", "Equal and perpendicular", "Equal and not necessarily perpendicular", "Unequal and not perpendicular"], correct: 2, explanation: "Rectangle diagonals are equal in length, but they only cross at 90° if the rectangle is a square." },
			{ chapter: "Ch 8: Quadrilaterals", question: "A rhombus with one angle of 90° is a:", options: ["Kite", "Trapezium", "Square", "Rectangle"], correct: 2, explanation: "If a rhombus (all sides equal) has one 90° angle, consecutive angles force all angles to be 90°, making it a square." },
			{ chapter: "Ch 8: Quadrilaterals", question: "The bisectors of angles of a parallelogram form a:", options: ["Rectangle", "Square", "Rhombus", "Parallelogram"], correct: 0, explanation: "The interior shape formed by the intersecting angle bisectors of a parallelogram is always a rectangle." },
			{ chapter: "Ch 8: Quadrilaterals", question: "In a parallelogram ABCD, if ∠A = 60°, then ∠C is:", options: ["120°", "60°", "90°", "30°"], correct: 1, explanation: "Opposite angles of a parallelogram are equal, so ∠C = ∠A = 60°." },
			{ chapter: "Ch 8: Quadrilaterals", question: "If the diagonals of a parallelogram are equal, then it is a:", options: ["Rhombus", "Rectangle", "Square", "Kite"], correct: 1, explanation: "A parallelogram with equal diagonals must have upright 90° corners, making it a rectangle." },

            // Chapter 9: Circles
            { chapter: "Ch 9: Circles", question: "The angle subtended by a diameter of a semicircle at any point on the circle is:", options: ["45°", "60°", "90°", "180°"], correct: 2, explanation: "An angle inscribed in a semicircle is always a right angle (90°)." },
            { chapter: "Ch 9: Circles", question: "Angles in the same segment of a circle are:", options: ["Complementary", "Supplementary", "Equal", "Unequal"], correct: 2, explanation: "A standard circle theorem states that any two angles subtended by the same arc at the circumference in the same segment are equal." },
            { chapter: "Ch 9: Circles", question: "Equal chords of a circle subtend equal angles at the:", options: ["Circumference", "Center", "Tangent", "Secant"], correct: 1, explanation: "A fundamental theorem of circles states that chords of equal length will always subtend equal angles at the center of the circle." },
			{ chapter: "Ch 9: Circles", question: "The region between a chord and either of its arcs is called a:", options: ["Sector", "Segment", "Semicircle", "Quadrant"], correct: 1, explanation: "A segment is the \"slice\" of a circle bounded by a chord and an arc. (A sector is bounded by two radii and an arc)." },
			{ chapter: "Ch 9: Circles", question: "The longest possible chord of a circle is its:", options: ["Radius", "Arc", "Diameter", "Secant"], correct: 2, explanation: "The diameter is a special chord that passes straight through the center, making it the longest distance across the circle." },
			{ chapter: "Ch 9: Circles", question: "Angles situated in the exact same segment of a circle are:", options: ["Supplementary", "Complementary", "Equal", "Right angles"], correct: 2, explanation: "A core circle theorem dictates that angles subtended by the same arc at any point on the remaining part of the circle are equal." },
			{ chapter: "Ch 9: Circles", question: "A cyclic parallelogram is specifically a:", options: ["Rectangle", "Square", "Rhombus", "Trapezium"], correct: 0, explanation: "Opposite angles of a cyclic quadrilateral sum to 180°. Since opposite angles of a parallelogram are equal, each must be 90°, making it a rectangle." },
			{ chapter: "Ch 9: Circles", question: "The mathematical center of a circle lies in the _______ of the circle.", options: ["Exterior", "Interior", "Boundary", "Tangent"], correct: 1, explanation: "The center point is enclosed within the boundary (circumference) of the circle, making it part of the interior space." },
			{ chapter: "Ch 9: Circles", question: "How many unique circles can pass through three distinct non-collinear points?", options: ["One", "Two", "Zero", "Infinite"], correct: 0, explanation: "Three points that don't form a straight line define exactly one unique circumcircle." },
			{ chapter: "Ch 9: Circles", question: "An arc is defined as a _______ when its ends match the ends of a diameter.", options: ["Semicircle", "Sector", "Segment", "Chord"], correct: 0, explanation: "A diameter splits a circle exactly in half, so the arc connecting the two ends forms a perfect semicircle (180°)." },
			{ chapter: "Ch 9: Circles", question: "The distance from the center to a 16 cm chord in a circle with a 10 cm radius is:", options: ["6 cm", "8 cm", "10 cm", "12 cm"], correct: 0, explanation: "The perpendicular bisects the chord (8 cm). Form a right triangle with the radius (10 cm). Distance = √(10² - 8²) = √36 = 6 cm." },
			{ chapter: "Ch 9: Circles", question: "Circles that share the exact same center point but have different radii are called:", options: ["Congruent circles", "Concentric circles", "Intersecting circles", "Cyclic circles"], correct: 1, explanation: "Concentric means 'sharing a center', forming rings like a bullseye target." },
			{ chapter: "Ch 9: Circles", question: "A perpendicular drawn from the center of a circle to a chord will always:", options: ["Bisect the chord", "Double the chord", "Be equal to the radius", "Be equal to the chord"], correct: 0, explanation: "A key circle theorem: A line dropped exactly at 90° from the center will cut any chord into two perfect halves." },
			{ chapter: "Ch 9: Circles", question: "The sum of either pair of opposite angles in a cyclic quadrilateral is always:", options: ["90°", "180°", "270°", "360°"], correct: 1, explanation: "For any four-sided shape inscribed completely inside a circle, its opposite diagonal angles will always supplement each other to 180°." },
			{ chapter: "Ch 9: Circles", question: "Chords of a circle that are perfectly equal in length are:", options: ["Parallel to each other", "Perpendicular to each other", "Equidistant from the center", "Diameters"], correct: 2, explanation: "If two chords are the exact same length, they must be situated the exact same perpendicular distance away from the center of the circle." },
			{ chapter: "Ch 9: Circles", question: "A chord of a circle is equal to the radius. The angle subtended by this chord at the center is:", options: ["30°", "45°", "60°", "90°"], correct: 2, explanation: "The chord and the two radii form an equilateral triangle, so the central angle must be 60°." },
			{ chapter: "Ch 9: Circles", question: "The number of common points in two concentric circles is:", options: ["1", "2", "0", "Infinite"], correct: 2, explanation: "Concentric circles are nested inside each other without ever touching, so they share 0 points." },
			{ chapter: "Ch 9: Circles", question: "If AB is a diameter of a circle and C is a point on the circle, then ∠ACB is:", options: ["60°", "90°", "120°", "180°"], correct: 1, explanation: "The angle subtended by a diameter at any point on the circumference is always a right angle (90°)." },
			{ chapter: "Ch 9: Circles", question: "Angles in the same segment of a circle are:", options: ["Complementary", "Supplementary", "Equal", "Unequal"], correct: 2, explanation: "Angles subtended by the same arc at the circumference in the same segment are always equal." },
			{ chapter: "Ch 9: Circles", question: "A cyclic quadrilateral ABCD has ∠A = 100°. What is ∠C?", options: ["80°", "100°", "90°", "120°"], correct: 0, explanation: "Opposite angles in a cyclic quadrilateral sum to 180°. 180° - 100° = 80°." },
			{ chapter: "Ch 9: Circles", question: "The region between an arc and the two radii joining the center to the endpoints of the arc is called a:", options: ["Sector", "Segment", "Chord", "Secant"], correct: 0, explanation: "A sector is the pie-shaped slice enclosed by two radii and an arc." },
			{ chapter: "Ch 9: Circles", question: "The longest chord of a circle is 10 cm. The radius of the circle is:", options: ["10 cm", "20 cm", "5 cm", "15 cm"], correct: 2, explanation: "The longest chord is the diameter (10 cm). Radius is half of the diameter, which is 5 cm." },

            // Chapter 10: Heron's Formula
			{ chapter: "Ch 10: Heron's Formula", question: "The sides of a triangle are 5 cm, 12 cm, and 13 cm. Its area is:", options: ["30 cm²", "60 cm²", "40 cm²", "65 cm²"], correct: 0, explanation: "This is a right triangle (5, 12, 13). Area = 1/2 × 5 × 12 = 30 cm²." },
			{ chapter: "Ch 10: Heron's Formula", question: "The perimeter of an equilateral triangle is 60 cm. Its area is:", options: ["100√3 cm²", "200√3 cm²", "400√3 cm²", "50√3 cm²"], correct: 0, explanation: "Side = 20. Area = (√3/4) × 20² = (√3/4) × 400 = 100√3 cm²." },
			{ chapter: "Ch 10: Heron's Formula", question: "The semi-perimeter of a triangle with sides 8 cm, 11 cm, and 13 cm is:", options: ["16 cm", "32 cm", "15 cm", "14 cm"], correct: 0, explanation: "Perimeter = 8 + 11 + 13 = 32. Semi-perimeter = 32 / 2 = 16 cm." },
			{ chapter: "Ch 10: Heron's Formula", question: "If the side of an equilateral triangle is tripled, its area becomes:", options: ["3 times", "6 times", "9 times", "27 times"], correct: 2, explanation: "Area scales by the square of the side. 3² = 9 times the original area." },
			{ chapter: "Ch 10: Heron's Formula", question: "Heron's formula is Area = √[s(s-a)(s-b)(s-c)]. What does 's' stand for?", options: ["Side length", "Semi-perimeter", "Square root", "Surface"], correct: 1, explanation: "'s' represents the semi-perimeter, which is exactly half of the triangle's total perimeter." },
			{ chapter: "Ch 10: Heron's Formula", question: "An isosceles right triangle has an area of 8 cm². The length of its hypotenuse is:", options: ["4 cm", "4√2 cm", "8 cm", "16 cm"], correct: 1, explanation: "Area = 1/2 a² = 8 ➔ a² = 16 ➔ a = 4. Hypotenuse = √(4²+4²) = √32 = 4√2 cm." },
			{ chapter: "Ch 10: Heron's Formula", question: "The area of a triangle whose sides are 3 cm, 4 cm and 5 cm is:", options: ["6 cm²", "12 cm²", "10 cm²", "15 cm²"], correct: 0, explanation: "Right triangle. Area = 1/2 × 3 × 4 = 6 cm²." },
            { chapter: "Ch 10: Heron's Formula", question: "The semi-perimeter of a triangle with sides 10 cm, 24 cm, and 26 cm is:", options: ["30 cm", "60 cm", "25 cm", "15 cm"], correct: 0, explanation: "Semi-perimeter (s) = (a + b + c) / 2. Here, s = (10 + 24 + 26) / 2 = 60 / 2 = 30 cm." },
            { chapter: "Ch 10: Heron's Formula", question: "If the perimeter of an equilateral triangle is 60m, its area is:", options: ["10√3 m²", "100√3 m²", "15√3 m²", "200√3 m²"], correct: 1, explanation: "Side length (a) = 60/3 = 20m. Area of equilateral triangle = (√3 / 4) × a² = (√3 / 4) × 400 = 100√3 m²." },
            { chapter: "Ch 10: Heron's Formula", question: "The area of an isosceles triangle having base 24 cm and length of one of the equal sides 13 cm is:", options: ["60 cm²", "120 cm²", "130 cm²", "312 cm²"], correct: 0, explanation: "Semi-perimeter s = (13+13+24)/2 = 25. Area = √(25(25-13)(25-13)(25-24)) = √(25 × 12 × 12 × 1) = 5 × 12 = 60 cm²." },
			{ chapter: "Ch 10: Heron's Formula", question: "The area of an equilateral triangle with a side length of 2√3 cm is:", options: ["√3 cm²", "3√3 cm²", "6 cm²", "9 cm²"], correct: 1, explanation: "Area = (√3 / 4) × a². Here, a² = (2√3)² = 12. So, (√3 / 4) × 12 = 3√3 cm²." },
			{ chapter: "Ch 10: Heron's Formula", question: "The semi-perimeter (s) of a triangle with sides a, b, and c is calculated as:", options: ["(a + b + c) / 2", "(a + b + c) / 3", "a + b + c", "(a × b × c) / 2"], correct: 0, explanation: "The prefix 'semi' means half. Therefore, the semi-perimeter is exactly half of the total perimeter (a + b + c)." },
			{ chapter: "Ch 10: Heron's Formula", question: "The area of a triangle with sides 3 cm, 4 cm, and 5 cm is:", options: ["6 cm²", "12 cm²", "10 cm²", "8 cm²"], correct: 0, explanation: "This forms a right-angled triangle (3²+4²=5²). Area = 1/2 × base × height = 1/2 × 3 × 4 = 6 cm². (Heron's formula yields the same)." },
			{ chapter: "Ch 10: Heron's Formula", question: "The area of an isosceles right triangle with a hypotenuse of 8 cm is:", options: ["16 cm²", "32 cm²", "64 cm²", "8 cm²"], correct: 0, explanation: "Let the equal sides be 'a'. By Pythagoras, a² + a² = 8² ➔ 2a² = 64 ➔ a² = 32. Area = 1/2 × base × height = 1/2 × a² = 1/2 × 32 = 16 cm²." },
			{ chapter: "Ch 10: Heron's Formula", question: "Which of the following is the correct representation of Heron's Formula for area?", options: ["√[s(s-a)(s-b)(s-c)]", "s(s-a)(s-b)(s-c)", "1/2 × base × height", "√[s(s+a)(s+b)(s+c)]"], correct: 0, explanation: "Heron's formula requires the square root of the semi-perimeter (s) multiplied by the differences of all three sides." },
			{ chapter: "Ch 10: Heron's Formula", question: "The shortcut area formula for an equilateral triangle with side 'a' is:", options: ["(√3/2)a²", "(√3/4)a²", "(√3)a²", "a²/2"], correct: 1, explanation: "Derived directly from Heron's formula when a=b=c, the area simplifies cleanly to (√3/4)a²." },
			{ chapter: "Ch 10: Heron's Formula", question: "A triangle's perimeter is 30 cm, and two sides are 12 cm each. Its area is:", options: ["9√15 cm²", "12√15 cm²", "15 cm²", "30 cm²"], correct: 0, explanation: "The third side is 30 - 12 - 12 = 6. Semi-perimeter (s) = 15. Area = √[15(15-12)(15-12)(15-6)] = √(15 × 3 × 3 × 9) = 9√15 cm²." },
			{ chapter: "Ch 10: Heron's Formula", question: "If every single side of a triangle is doubled, the ratio of the new area to the old area is:", options: ["1:2", "2:1", "4:1", "1:4"], correct: 2, explanation: "Area scales with the square of the linear dimensions. If sides scale by 2, area scales by 2² = 4. The ratio is 4:1." },
			{ chapter: "Ch 10: Heron's Formula", question: "Heron's Formula can be used to calculate the area of:", options: ["Only right triangles", "Only equilateral triangles", "Any type of triangle", "Only quadrilaterals"], correct: 2, explanation: "Heron's Formula is universally applicable to every single type of triangle, provided you know the lengths of all three sides." },
			{ chapter: "Ch 10: Heron's Formula", question: "The basic formula for the area of a triangle, without using Heron's, is:", options: ["base × height", "1/2 × base × height", "2 × base × height", "base + height"], correct: 1, explanation: "The standard geometric formula for triangle area is half of the base multiplied by the perpendicular height." },
			{ chapter: "Ch 10: Heron's Formula", question: "The semi-perimeter of a triangle with sides 10 cm, 10 cm, and 12 cm is:", options: ["16 cm", "32 cm", "15 cm", "20 cm"], correct: 0, explanation: "Perimeter = 10 + 10 + 12 = 32. The semi-perimeter (s) is half of that: 32 / 2 = 16 cm." },
			{ chapter: "Ch 10: Heron's Formula", question: "What is the area of an isosceles triangle with sides 10 cm, 10 cm, and 12 cm?", options: ["24 cm²", "36 cm²", "48 cm²", "60 cm²"], correct: 2, explanation: "Using Heron's: s = 16. Area = √[16(16-10)(16-10)(16-12)] = √(16 × 6 × 6 × 4) = 4 × 6 × 2 = 48 cm²." },
			{ chapter: "Ch 10: Heron's Formula", question: "Two parallelograms are on the exact same base and lie between the same parallel lines. The ratio of their areas is:", options: ["1:2", "2:1", "1:1", "3:1"], correct: 2, explanation: "A fundamental theorem states that parallelograms on the same base and between the same parallels are always equal in area." },
			{ chapter: "Ch 10: Heron's Formula", question: "If a triangle and a parallelogram are on the same base and between the same parallels, the ratio of the area of the triangle to the area of the parallelogram is:", options: ["1:3", "1:2", "1:1", "2:1"], correct: 1, explanation: "The area of the triangle is exactly half the area of the parallelogram when they share the same base and height." },
			{ chapter: "Ch 10: Heron's Formula", question: "The median of a triangle divides it into two:", options: ["Congruent triangles", "Isosceles triangles", "Triangles of equal area", "Right-angled triangles"], correct: 2, explanation: "A median cuts the base exactly in half. Since both resulting triangles share the same height and have equal bases, their areas are equal." },
			{ chapter: "Ch 10: Heron's Formula", question: "If the area of a parallelogram ABCD is 50 cm², then the area of a triangle on the same base AB and between the same parallels is:", options: ["25 cm²", "50 cm²", "100 cm²", "12.5 cm²"], correct: 0, explanation: "The triangle's area is exactly half of the parallelogram's area. 50 / 2 = 25 cm²." },
			{ chapter: "Ch 10: Heron's Formula", question: "ABCD is a parallelogram. P is any point on the side CD. If the area of ABCD is 80 cm², what is the area of ΔAPB?", options: ["20 cm²", "40 cm²", "60 cm²", "80 cm²"], correct: 1, explanation: "ΔAPB and parallelogram ABCD share the base AB and lie between the same parallels (AB and CD). Therefore, the triangle is half the area of the parallelogram." },
			{ chapter: "Ch 10: Heron's Formula", question: "In ΔABC, D is the midpoint of BC, and E is the midpoint of the median AD. The area of ΔBED is:", options: ["1/2 area(ABC)", "1/3 area(ABC)", "1/4 area(ABC)", "Equal to area(ABC)"], correct: 2, explanation: "Median AD splits ABC into two equal halves. Median BE of ΔABD splits it into two equal halves again. Half of a half is 1/4." },
			{ chapter: "Ch 10: Heron's Formula", question: "If a triangle and a parallelogram are on the same base and between the same parallels, and the area of the triangle is 18 cm², the area of the parallelogram is:", options: ["9 cm²", "18 cm²", "24 cm²", "36 cm²"], correct: 3, explanation: "The parallelogram's area is double the triangle's area. 18 × 2 = 36 cm²." },
			{ chapter: "Ch 10: Heron's Formula", question: "In a parallelogram ABCD, the diagonals AC and BD intersect at O. The area of ΔAOB is:", options: ["1/2 area(ABCD)", "1/3 area(ABCD)", "1/4 area(ABCD)", "Equal to area(ABCD)"], correct: 2, explanation: "The diagonals of a parallelogram divide it into four distinct triangles that are all perfectly equal in area." },
			{ chapter: "Ch 10: Heron's Formula", question: "If the diagonals of a quadrilateral divide it into four triangles of equal area, the quadrilateral must be a:", options: ["Parallelogram", "Trapezium", "Kite", "Cyclic quadrilateral"], correct: 0, explanation: "Only a parallelogram (including its sub-types like squares and rhombuses) is divided into four equal-area triangles by its intersecting diagonals." },
			{ chapter: "Ch 10: Heron's Formula", question: "Two parallelograms have equal bases and lie between the same parallels. If the altitude of the first is 7 cm, the altitude of the second is:", options: ["3.5 cm", "7 cm", "14 cm", "Cannot be determined"], correct: 1, explanation: "Lying between the same parallel lines means the perpendicular distance (altitude) between those lines is constant everywhere." },
			{ chapter: "Ch 10: Heron's Formula", question: "P and Q are any two points lying on the sides DC and AD respectively of a parallelogram ABCD. Which of the following is true?", options: ["area(APB) > area(BQC)", "area(APB) < area(BQC)", "area(APB) = area(BQC)", "No relationship exists"], correct: 2, explanation: "ΔAPB shares base AB with the parallelogram, so it's half its area. ΔBQC shares base BC with the parallelogram, so it's also half its area." },
			{ chapter: "Ch 10: Heron's Formula", question: "A rectangle and a parallelogram are on the same base and between the same parallels. The perimeter of the parallelogram is:", options: ["Equal to the rectangle", "Less than the rectangle", "Greater than the rectangle", "Half the rectangle"], correct: 2, explanation: "While their areas are equal, the slanted sides of a non-rectangular parallelogram are hypotenuses of right triangles, making them longer than the straight sides of the rectangle." },
			{ chapter: "Ch 10: Heron's Formula", question: "In trapezium ABCD where AB || DC, diagonals AC and BD intersect at O. Which two triangles always have equal areas?", options: ["ΔAOB and ΔCOD", "ΔAOD and ΔBOC", "ΔABD and ΔBCD", "ΔABC and ΔADC"], correct: 1, explanation: "ΔABD and ΔABC are on the same base AB and between same parallels. Subtracting the common ΔAOB from both leaves area(ΔAOD) = area(ΔBOC)." },
			{ chapter: "Ch 10: Heron's Formula", question: "If the ratio of the bases of two triangles is 3:5 and they lie between the same parallel lines, the ratio of their areas is:", options: ["3:5", "9:25", "5:3", "1:1"], correct: 0, explanation: "Since they lie between the same parallels, their heights are identical. Therefore, their areas are directly proportional to their bases (3:5)." },
			{ chapter: "Ch 10: Heron's Formula", question: "ABC is a triangle and D is a point on BC such that BD = DC. The ratio of area(ΔABD) to area(ΔADC) is:", options: ["2:1", "1:2", "1:1", "4:1"], correct: 2, explanation: "Because BD = DC, AD is a median. A median divides a triangle into two triangles of perfectly equal area, creating a 1:1 ratio." },
			{ chapter: "Ch 10: Heron's Formula", question: "The area of a rhombus can be calculated directly by taking half the product of its:", options: ["Sides", "Diagonals", "Altitudes", "Vertices"], correct: 1, explanation: "The standard area formula specifically for a rhombus (and a kite) is 1/2 × (Diagonal 1) × (Diagonal 2)." },
			{ chapter: "Ch 10: Heron's Formula", question: "Two triangles have equal areas. If their heights are in the ratio 2:3, what is the ratio of their corresponding bases?", options: ["2:3", "3:2", "4:9", "1:1"], correct: 1, explanation: "Area = 1/2 × b × h. If Area 1 = Area 2, then b1 × h1 = b2 × h2. So b1/b2 = h2/h1 = 3/2." },
			{ chapter: "Ch 10: Heron's Formula", question: "For any two figures to be 'on the same base and between the same parallels', they must:", options: ["Have the exact same perimeter", "Share a common base and have opposite vertices on a line parallel to that base", "Be congruent", "Be regular polygons"], correct: 1, explanation: "This is the strict geometric definition required to apply the equal area theorems." },
			{ chapter: "Ch 10: Heron's Formula", question: "In ΔABC, points D, E, and F are the midpoints of sides BC, CA, and AB respectively. The area of ΔDEF is:", options: ["1/2 area(ABC)", "1/3 area(ABC)", "1/4 area(ABC)", "1/6 area(ABC)"], correct: 2, explanation: "Connecting the three midpoints of any triangle divides the original triangle into four smaller, congruent triangles of equal area." },
			{ chapter: "Ch 10: Heron's Formula", question: "If a square and a rhombus sit on the exact same base and lie between the same parallels, their areas are:", options: ["Equal", "Square is larger", "Rhombus is larger", "Cannot be compared"], correct: 0, explanation: "Since a square is just a specific type of parallelogram, the theorem applies perfectly: any parallelograms on the same base and between same parallels have equal areas." },

            // Chapter 11: Surface Areas and Volumes
            { chapter: "Ch 11: Surface Area & Volume", question: "The total surface area of a hemisphere of radius r is:", options: ["πr²", "2πr²", "3πr²", "4πr²"], correct: 2, explanation: "The curved surface area of a hemisphere is 2πr², and the flat circular base area is πr². Total = 3πr²." },
            { chapter: "Ch 11: Surface Area & Volume", question: "If the radius of a sphere is doubled, the ratio of its initial volume to the new volume is:", options: ["1:2", "1:4", "1:8", "1:16"], correct: 2, explanation: "Volume of a sphere is proportional to r³. If radius becomes 2r, volume becomes proportional to (2r)³ = 8r³. The ratio is 1:8." },
            { chapter: "Ch 11: Surface Area & Volume", question: "The volume of a right circular cone of radius r and height h is:", options: ["πr²h", "1/3 πr²h", "2/3 πr²h", "4/3 πr²h"], correct: 1, explanation: "The volume of a cone is exactly one-third the volume of a cylinder that shares the same base radius and height." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The lateral surface area of a cube is 256 m². The volume of the cube is:", options: ["512 m³", "64 m³", "216 m³", "256 m³"], correct: 0, explanation: "Lateral surface area (4 sides) = 4a² = 256 ➔ a² = 64 ➔ a = 8m. Volume = a³ = 8³ = 512 m³." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The surface area of a sphere with a radius of 14 cm is:", options: ["2464 cm²", "2446 cm²", "2644 cm²", "2664 cm²"], correct: 0, explanation: "Surface Area = 4πr² = 4 × (22/7) × (14)² = 4 × (22/7) × 196 = 4 × 22 × 28 = 2464 cm²." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The lateral (curved) surface area of a cylinder of radius r and height h is:", options: ["πr²h", "2πrh", "2πr(r + h)", "πrh"], correct: 1, explanation: "The lateral surface area refers only to the curved outer wall, ignoring the top and bottom circles, which is calculated as 2πrh." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The volume of a solid hemisphere is given by the formula:", options: ["4/3 πr³", "2/3 πr³", "πr³h", "1/3 πr²h"], correct: 1, explanation: "A hemisphere is exactly half of a full sphere. Since a sphere's volume is 4/3 πr³, a hemisphere is 2/3 πr³." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "If the volume of a sphere is numerically equal to its surface area, then its radius is:", options: ["1 unit", "2 units", "3 units", "4 units"], correct: 2, explanation: "Set Volume = Surface Area: 4/3 πr³ = 4πr². Canceling 4πr² from both sides leaves r/3 = 1, meaning r = 3." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The slant height (l) of a right circular cone is calculated using:", options: ["√(r² + h²)", "r² + h²", "√(r² - h²)", "√(h² - r²)"], correct: 0, explanation: "The radius, height, and slant height form a right triangle. By Pythagoras, slant height l = √(r² + h²)." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The total volume capacity of a solid cylinder is:", options: ["1/3 πr²h", "2πrh", "πr²h", "4/3 πr³"], correct: 2, explanation: "The volume of a prism/cylinder is its base area multiplied by its height. The circular base is πr², so Volume = πr²h." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The Total Surface Area of a solid hemisphere of radius 7 cm is:", options: ["154π cm²", "147π cm²", "49π cm²", "98π cm²"], correct: 1, explanation: "TSA = 3πr² (curved surface + flat base). Plug in r=7: 3 × π × 49 = 147π cm²." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "If the ratio of the radii of two spheres is 1:3, the ratio of their volumes is:", options: ["1:9", "1:3", "1:27", "1:6"], correct: 2, explanation: "Volume of a sphere scales with the cube of the radius (r³). The ratio becomes 1³ : 3³ = 1:27." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The total surface area of a standard cuboid (length l, breadth b, height h) is:", options: ["lbh", "2(l+b)h", "2(lb + bh + hl)", "6(lbh)"], correct: 2, explanation: "A cuboid has 6 rectangular faces. The area sums to two of each face pairing: 2×(length×breadth + breadth×height + height×length)." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "If the volume of a perfect cube is 64 cm³, what is the length of its edge?", options: ["2 cm", "4 cm", "8 cm", "16 cm"], correct: 1, explanation: "Volume of a cube is side³. Since 4 × 4 × 4 = 64, the edge length must be 4 cm." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The Total Surface Area of a solid right circular cylinder is:", options: ["2πrh", "πr²h", "2πr(r + h)", "πr(r + l)"], correct: 2, explanation: "TSA includes the curved wall (2πrh) plus the top and bottom circles (2πr²). Factoring out 2πr gives 2πr(r + h)." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The ratio of the volume of a cone to a cylinder sharing the exact same base radius and height is:", options: ["1:2", "1:3", "3:1", "1:4"], correct: 1, explanation: "A cylinder's volume is πr²h. A cone's volume is (1/3)πr²h. Thus, it takes exactly 3 cones to fill 1 cylinder." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The volume of a sphere of radius r is:", options: ["4/3 πr³", "2/3 πr³", "4πr²", "3πr²"], correct: 0, explanation: "The standard geometric formula for the volume of a full sphere is 4/3 πr³." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "If the radius of a cylinder is doubled and height halved, the volume will be:", options: ["Doubled", "Halved", "Unchanged", "Quadrupled"], correct: 0, explanation: "V = πr²h. New V = π(2r)²(h/2) = π(4r²)(h/2) = 2πr²h. The volume doubles." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The lateral surface area of a cube with edge 'a' is:", options: ["6a²", "4a²", "3a²", "a³"], correct: 1, explanation: "Lateral area ignores the top and bottom faces, leaving 4 square faces: 4a²." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The curved surface area of a cone is:", options: ["πrh", "πr²h", "πrl", "2πrl"], correct: 2, explanation: "The curved (lateral) surface of a right circular cone is π multiplied by radius and slant height (l)." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The total surface area of a hemisphere is:", options: ["2πr²", "3πr²", "4πr²", "2/3 πr³"], correct: 1, explanation: "The curved bowl part is 2πr² and the flat circular lid is πr², totaling 3πr²." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "1 liter is equal to how many cubic centimeters (cm³)?", options: ["10", "100", "1000", "10000"], correct: 2, explanation: "By metric definition, 1 liter of volume occupies exactly 1000 cm³." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "The volume of a cone is 1570 cm³ and its base area is 314 cm². Its height is:", options: ["5 cm", "10 cm", "15 cm", "20 cm"], correct: 2, explanation: "V = (1/3) × BaseArea × h. 1570 = (1/3) × 314 × h ➔ 4710 = 314h ➔ h = 15." },

            // Chapter 12: Statistics
            { chapter: "Ch 12: Statistics", question: "The class mark of the class 130 - 150 is:", options: ["130", "135", "140", "150"], correct: 2, explanation: "The class mark (midpoint) is (Upper Limit + Lower Limit) / 2. So, (130 + 150) / 2 = 280 / 2 = 140." },
            { chapter: "Ch 12: Statistics", question: "The median of the data: 15, 28, 72, 56, 44, 32, 31, 43 is:", options: ["37.5", "32", "43", "38"], correct: 0, explanation: "First, arrange in ascending order: 15, 28, 31, 32, 43, 44, 56, 72. With 8 numbers, median is the average of 4th and 5th: (32 + 43) / 2 = 37.5." },
			{ chapter: "Ch 12: Statistics", question: "The mode of the data 4, 6, 9, 6, 4, 2, 4, 8, 6, 4, 3, 4, 6 is:", options: ["4", "6", "9", "3"], correct: 0, explanation: "The mode is the value that appears most frequently. Here, 4 appears five times, which is more than any other number in the set." },
			{ chapter: "Ch 12: Statistics", question: "The range of the data 25, 18, 20, 22, 16, 6, 17, 15, 12, 30, 32, 10, 19, 8, 11 is:", options: ["10", "15", "18", "26"], correct: 3, explanation: "Range is the difference between the highest and lowest values in the dataset. Highest = 32, Lowest = 6. 32 - 6 = 26." },
			{ chapter: "Ch 12: Statistics", question: "In a frequency distribution, the mid-value of a class is 10 and the class width is 6. The lower limit of the class is:", options: ["6", "7", "8", "12"], correct: 1, explanation: "Lower limit = Mid-value - (Class Width / 2). So, 10 - (6 / 2) = 10 - 3 = 7." },
			{ chapter: "Ch 12: Statistics", question: "Which of the following is NOT a measure of central tendency?", options: ["Mean", "Median", "Mode", "Range"], correct: 3, explanation: "Mean, Median, and Mode describe the center or typical value of a dataset. Range describes the spread (dispersion) of the data." },
			{ chapter: "Ch 12: Statistics", question: "The mean of the first five prime numbers is:", options: ["3.6", "5.6", "5.2", "4.8"], correct: 1, explanation: "The first five primes are 2, 3, 5, 7, and 11. Sum = 2 + 3 + 5 + 7 + 11 = 28. Mean = 28 / 5 = 5.6." },
			{ chapter: "Ch 12: Statistics", question: "The calculated mean of the first 5 natural numbers is:", options: ["2", "3", "4", "5"], correct: 1, explanation: "The first five natural numbers are 1, 2, 3, 4, 5. Sum = 15. Mean = 15 / 5 = 3." },
			{ chapter: "Ch 12: Statistics", question: "If every observation in a data set is increased by exactly 5, the new mean:", options: ["Remains unchanged", "Increases by exactly 5", "Decreases by 5", "Is multiplied by 5"], correct: 1, explanation: "Shifting every single data point up by a constant shifts the center of gravity (the mean) up by that exact same constant." },
			{ chapter: "Ch 12: Statistics", question: "When plotting a frequency polygon on a graph, the x-axis represents the:", options: ["Frequencies", "Class Limits", "Class Marks (Midpoints)", "Tally Marks"], correct: 2, explanation: "A frequency polygon connects dots plotted at the exact center of each class interval, known as the class marks." },
			{ chapter: "Ch 12: Statistics", question: "The mathematical difference between the upper limit and lower limit of a class is called the:", options: ["Class Mark", "Class Size (Width)", "Frequency", "Range"], correct: 1, explanation: "Subtracting the lower bound from the upper bound gives you the interval width, formally called the Class Size." },
			{ chapter: "Ch 12: Statistics", question: "Tally marks are primarily used in statistics to find the:", options: ["Class limits", "Frequency", "Mean", "Range"], correct: 1, explanation: "Tally marks are a counting tool used to quickly record the number of times (frequency) a specific data point occurs." },
			{ chapter: "Ch 12: Statistics", question: "The calculated mean of the first 5 whole numbers is:", options: ["2", "2.5", "3", "1.5"], correct: 0, explanation: "The first 5 whole numbers include zero: 0, 1, 2, 3, 4. Sum = 10. Mean = 10 / 5 = 2." },
			{ chapter: "Ch 12: Statistics", question: "Data collected directly by an investigator for a specific inquiry is known as:", options: ["Secondary data", "Primary data", "Grouped data", "Raw data"], correct: 1, explanation: "Primary data is collected first-hand by the researcher, whereas secondary data is sourced from existing records." },
			{ chapter: "Ch 12: Statistics", question: "The class mark (midpoint) of the class interval 10 - 20 is:", options: ["5", "10", "15", "30"], correct: 2, explanation: "The class mark is the exact center: (Lower Limit + Upper Limit) / 2. Here, (10 + 20) / 2 = 15." },
			{ chapter: "Ch 12: Statistics", question: "The mean of the first 5 prime numbers is:", options: ["5.6", "5.2", "4.8", "6.2"], correct: 0, explanation: "Primes: 2, 3, 5, 7, 11. Sum = 28. Mean = 28 / 5 = 5.6." },
			{ chapter: "Ch 12: Statistics", question: "The median of 2, 4, 6, 8, 10 is:", options: ["4", "6", "8", "10"], correct: 1, explanation: "The data is already sorted. The exact middle value of these 5 numbers is 6." },
			{ chapter: "Ch 12: Statistics", question: "The mode of 1, 2, 2, 3, 3, 3, 4, 4 is:", options: ["2", "3", "4", "1"], correct: 1, explanation: "Mode is the most frequent number. 3 appears three times, which is the most." },
			{ chapter: "Ch 12: Statistics", question: "The class mark of the interval 20 - 30 is:", options: ["20", "25", "30", "10"], correct: 1, explanation: "Class mark is the midpoint: (20 + 30) / 2 = 25." },
			{ chapter: "Ch 12: Statistics", question: "The difference between the maximum and minimum observations is called:", options: ["Mean", "Median", "Mode", "Range"], correct: 3, explanation: "The range measures the total spread of the dataset from lowest to highest." },
			{ chapter: "Ch 12: Statistics", question: "In a histogram, the area of each rectangle is proportional to the:", options: ["Class mark", "Class size", "Frequency", "Cumulative frequency"], correct: 2, explanation: "The height (and thus area, for uniform widths) of the bars represents the frequency of the data." },
			{ chapter: "Ch 12: Statistics", question: "If the mean of 6, 4, 7, p, and 10 is 8, then p is:", options: ["10", "12", "13", "14"], correct: 2, explanation: "Sum = 6+4+7+p+10 = 27+p. Mean = (27+p)/5 = 8 ➔ 27+p = 40 ➔ p = 13." },
    


			// Chapter 13: Probability
			{ chapter: "Ch 13: Probability", question: "A coin is tossed 1000 times with the following frequencies: Head: 455, Tail: 545. The empirical probability of getting a head is:", options: ["0.45", "0.455", "0.545", "0.55"], correct: 1, explanation: "Probability = (Number of times Head appeared) / (Total tosses) = 455 / 1000 = 0.455." },
			{ chapter: "Ch 13: Probability", question: "The mathematical probability of a completely impossible event is:", options: ["0", "1", "0.5", "-1"], correct: 0, explanation: "If an event absolutely cannot happen under any circumstances, its probability is 0 (or 0%)." },
			{ chapter: "Ch 13: Probability", question: "If the probability of an event happening is P(E) = 0.37, then the probability of the event NOT happening is:", options: ["0.37", "0.63", "0.57", "1.37"], correct: 1, explanation: "The sum of the probability of an event happening and not happening is always 1. So, P(not E) = 1 - 0.37 = 0.63." },
			{ chapter: "Ch 13: Probability", question: "A fair die is thrown once. The probability of getting an even prime number is:", options: ["1/6", "1/3", "1/2", "2/3"], correct: 0, explanation: "The only even prime number in existence is 2. On a 6-sided die, '2' appears only once, making the probability 1 out of 6." },
			{ chapter: "Ch 13: Probability", question: "Which of the following cannot be the empirical probability of an event?", options: ["2/3", "-1.5", "15%", "0.7"], correct: 1, explanation: "Probability must always be a value between 0 and 1 (inclusive). It can never be a negative number." },
			{ chapter: "Ch 13: Probability", question: "The mathematical probability of a 'sure' or guaranteed event is:", options: ["0", "1", "0.5", "Greater than 1"], correct: 1, explanation: "If an event is 100% certain to happen, its probability translates mathematically to 1." },
			{ chapter: "Ch 13: Probability", question: "A fair coin is tossed. What is the probability of getting neither a head nor a tail?", options: ["0", "1", "0.5", "0.25"], correct: 0, explanation: "A coin must land on either heads or tails. Landing on neither is physically impossible, resulting in a probability of 0." },
			{ chapter: "Ch 13: Probability", question: "In a standard deck of 52 cards, the probability of drawing a red face card is:", options: ["3/26", "3/52", "6/26", "1/13"], correct: 0, explanation: "There are 6 red face cards (Jack, Queen, King of Hearts & Diamonds). 6 / 52 simplifies to 3 / 26." },
			{ chapter: "Ch 13: Probability", question: "A bag holds 3 red balls and 5 black balls. The probability of randomly drawing a red ball is:", options: ["3/5", "5/8", "3/8", "1/8"], correct: 2, explanation: "Total number of balls = 3 + 5 = 8. Number of red balls = 3. Probability = 3 / 8." }, 
			{ chapter: "Ch 13: Probability", question: "The probability of an impossible event is:", options: ["1", "0", "0.5", "-1"], correct: 1, explanation: "If an event cannot physically happen, it has a 0% chance, or a probability of 0." },
			{ chapter: "Ch 13: Probability", question: "The probability of a sure event is:", options: ["0", "1", "100", "0.5"], correct: 1, explanation: "A guaranteed event has a 100% chance, which mathematically equates to 1." },
			{ chapter: "Ch 13: Probability", question: "If P(E) = 0.05, then P(Not E) is:", options: ["0.95", "0.05", "1.05", "0.9"], correct: 0, explanation: "P(E) + P(Not E) = 1. So, 1 - 0.05 = 0.95." },
			{ chapter: "Ch 13: Probability", question: "A coin is tossed once. Probability of getting a tail is:", options: ["1", "0", "1/2", "2"], correct: 2, explanation: "There is 1 tail out of 2 possible outcomes (heads or tails), so 1/2." },
			{ chapter: "Ch 13: Probability", question: "A die is thrown once. Probability of getting a prime number is:", options: ["1/2", "1/3", "2/3", "1/6"], correct: 0, explanation: "Primes on a die are 2, 3, 5. That's 3 outcomes out of 6, which simplifies to 1/2." },
			{ chapter: "Ch 13: Probability", question: "From a deck of 52 cards, probability of drawing an ace is:", options: ["1/13", "1/52", "4/13", "1/4"], correct: 0, explanation: "There are 4 aces in a 52-card deck. 4/52 simplifies to 1/13." },
			{ chapter: "Ch 13: Probability", question: "The sum of all probabilities of mutually exclusive exhaustive events is:", options: ["0", "1", "0.5", "Infinity"], correct: 1, explanation: "When all possible distinct outcomes are added together, they must equal 100% (or 1)." },
			{ chapter: "Ch 13: Probability", question: "If two fair coins are tossed simultaneously, the probability of getting exactly two heads is:", options: ["1/2", "1/4", "3/4", "1/8"], correct: 1, explanation: "The four possible outcomes are HH, HT, TH, TT. Only one outcome is HH, making the probability 1 out of 4." },
			{ chapter: "Ch 13: Probability", question: "A fair 6-sided die is rolled. The probability of rolling a number strictly greater than 4 is:", options: ["1/6", "1/3", "1/2", "2/3"], correct: 1, explanation: "The numbers greater than 4 on a standard die are 5 and 6. This gives 2 successful outcomes out of 6 total, which simplifies to 1/3." },
			{ chapter: "Ch 13: Probability", question: "If one card is drawn from a well-shuffled standard deck of 52 cards, the probability it is a Spade is:", options: ["1/52", "1/13", "1/4", "1/2"], correct: 2, explanation: "A deck has 4 suits, with 13 cards in each suit. 13 Spades out of 52 total cards simplifies to 1/4 (or 25%)." },
    

    
			// More Mixed Chapter Questions
			{ chapter: "Ch 1: Number System", question: "The value of (81)^(0.25) is:", options: ["3", "9", "27", "81"], correct: 0, explanation: "0.25 is 1/4. The 4th root of 81 (3 × 3 × 3 × 3) is 3." },
			{ chapter: "Ch 2: Polynomials", question: "If a polynomial is of degree 1, it is called a:", options: ["Quadratic", "Cubic", "Linear", "Constant"], correct: 2, explanation: "A degree of 1 creates a straight line when graphed, hence 'linear'." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The distance between points (0,0) and (3,4) is:", options: ["5", "7", "12", "25"], correct: 0, explanation: "Using the distance formula or Pythagoras: √(3² + 4²) = √25 = 5." },
			{ chapter: "Ch 4: Linear Equations", question: "Which equation represents the y-axis?", options: ["y = 0", "x = 0", "x = y", "x + y = 0"], correct: 1, explanation: "Every single point precisely on the y-axis has an x-coordinate of 0." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "According to Euclid, a line segment can be extended:", options: ["Finitely", "Infinitely", "Only to 100 units", "Cannot be extended"], correct: 1, explanation: "Euclid's second postulate says a terminated line (segment) can be produced indefinitely." },
			{ chapter: "Ch 6: Lines & Angles", question: "The sum of interior angles on the same side of a transversal is:", options: ["90°", "180°", "360°", "Equal"], correct: 1, explanation: "Co-interior angles between parallel lines are always supplementary (180°)." },
			{ chapter: "Ch 7: Triangles", question: "In a right triangle, the hypotenuse is 10 and one side is 6. The third side is:", options: ["8", "12", "16", "64"], correct: 0, explanation: "By Pythagoras: 10² = 6² + x² ➔ 100 - 36 = x² ➔ 64 = x² ➔ x = 8." },
			{ chapter: "Ch 8: Quadrilaterals", question: "A parallelogram with all equal sides but no 90° angles is a:", options: ["Square", "Rectangle", "Rhombus", "Kite"], correct: 2, explanation: "A rhombus has 4 equal sides but does not require upright 90° corners like a square." },
			{ chapter: "Ch 9: Circles", question: "The angle in a semicircle is a:", options: ["Acute angle", "Obtuse angle", "Right angle", "Straight angle"], correct: 2, explanation: "A triangle inscribed in a semicircle always forms a perfect 90° right angle." },
			{ chapter: "Ch 10: Heron's Formula", question: "The area of a triangle with base 10cm and height 5cm is:", options: ["25 cm²", "50 cm²", "100 cm²", "12.5 cm²"], correct: 0, explanation: "Area = 1/2 × base × height = 1/2 × 10 × 5 = 25 cm²." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "Volume of a cuboid is:", options: ["lb", "lbh", "2(lb+bh+hl)", "l+b+h"], correct: 1, explanation: "Volume requires multiplying all three dimensions: length × breadth × height." },
			{ chapter: "Ch 12: Statistics", question: "The value occurring most frequently in a dataset is the:", options: ["Mean", "Median", "Mode", "Range"], correct: 2, explanation: "By definition, the mode is the most popular/frequent data point." },
			{ chapter: "Ch 13: Probability", question: "Probability of getting an 8 on a standard 6-sided die is:", options: ["1/6", "0", "1/8", "1"], correct: 1, explanation: "The numbers only go up to 6, making 8 an impossible event (probability 0)." },
			{ chapter: "Ch 1: Number System", question: "√3 is a/an:", options: ["Rational number", "Irrational number", "Integer", "Fraction"], correct: 1, explanation: "3 is not a perfect square, so its root yields a non-repeating decimal." },
			{ chapter: "Ch 2: Polynomials", question: "The value of 102² using identities is:", options: ["10404", "10004", "10204", "10400"], correct: 0, explanation: "(100 + 2)² = 10000 + 4 + 400 = 10404." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "Point (-4, 5) lies in quadrant:", options: ["I", "II", "III", "IV"], correct: 1, explanation: "Negative x and positive y maps to the top-left (second) quadrant." },
			{ chapter: "Ch 4: Linear Equations", question: "Which of the following is a solution to x + y = 7?", options: ["(2, 4)", "(3, 4)", "(5, 3)", "(1, 5)"], correct: 1, explanation: "Substitute x=3 and y=4: 3 + 4 = 7." },
			{ chapter: "Ch 5: Euclidean Geometry", question: "A straight line has:", options: ["No endpoints", "One endpoint", "Two endpoints", "Infinite thickness"], correct: 0, explanation: "A true geometric line extends infinitely in both directions with no ends." },
			{ chapter: "Ch 6: Lines & Angles", question: "If two supplementary angles are equal, each is:", options: ["45°", "90°", "180°", "60°"], correct: 1, explanation: "x + x = 180° ➔ 2x = 180° ➔ x = 90°." },
			{ chapter: "Ch 7: Triangles", question: "A triangle with all sides unequal is called:", options: ["Isosceles", "Equilateral", "Scalene", "Right"], correct: 2, explanation: "Scalene triangles possess no equal sides and no equal angles." },
			{ chapter: "Ch 8: Quadrilaterals", question: "Opposite angles of a cyclic quadrilateral sum to:", options: ["90°", "180°", "270°", "360°"], correct: 1, explanation: "Any four-sided shape inscribed in a circle has supplementary opposite angles." },
			{ chapter: "Ch 9: Circles", question: "Distance from the center to a point on the circle is the:", options: ["Chord", "Diameter", "Radius", "Arc"], correct: 2, explanation: "The radius connects the center point to the outer boundary." },
			{ chapter: "Ch 10: Heron's Formula", question: "Semi-perimeter of a triangle with sides 3, 4, 5 is:", options: ["6", "12", "7", "8"], correct: 0, explanation: "Perimeter = 12. Semi-perimeter = 12/2 = 6." },
			{ chapter: "Ch 11: Surface Area & Volume", question: "Surface area of a sphere of radius r is:", options: ["2πr²", "3πr²", "4πr²", "4/3πr³"], correct: 2, explanation: "The total outer skin of a sphere requires 4πr² of area." },
			{ chapter: "Ch 12: Statistics", question: "The median of 1, 3, 5, 7, 9 is:", options: ["3", "5", "7", "9"], correct: 1, explanation: "5 sits exactly in the middle of the sorted list." },
			{ chapter: "Ch 13: Probability", question: "Probability of drawing a black card from a standard deck is:", options: ["1/4", "1/2", "3/4", "1/13"], correct: 1, explanation: "Half the deck (26/52) is red, and half is black." },
			{ chapter: "Ch 1: Number System", question: "The number 0 is:", options: ["Positive", "Negative", "Neither", "Irrational"], correct: 2, explanation: "Zero is a neutral integer, neither positive nor negative." },
			{ chapter: "Ch 2: Polynomials", question: "What is the degree of x^5 - x^4 + 3?", options: ["4", "5", "3", "1"], correct: 1, explanation: "The highest exponent on any variable is 5." },
			{ chapter: "Ch 3: Coordinate Geometry", question: "The y-coordinate of a point is also called the:", options: ["Origin", "Quadrant", "Abscissa", "Ordinate"], correct: 3, explanation: "In Cartesian terms, x is the abscissa and y is the ordinate." }
            
    ];